import test from "node:test";
import assert from "node:assert/strict";
import { contains } from "../../src/interval.mjs";

test("contains: exact lower endpoint is inside (kills m4's point>start guard)", () => {
	assert.equal(contains([{ start: 5, end: 10 }], 5), true);
});

test("contains: exact upper endpoint is inside (kills m5's point<end guard)", () => {
	assert.equal(contains([{ start: 5, end: 10 }], 10), true);
});

