import test from "node:test";
import assert from "node:assert/strict";
import { mergeIntervals } from "../../src/interval.mjs";

test("mergeIntervals: touching intervals with a gap of exactly one merge (kills m2's <=last.end guard)", () => {
	assert.deepEqual(mergeIntervals([{ start: 1, end: 3 }, { start: 4, end: 6 }]), [{ start: 1, end: 6 }]);
});

test("mergeIntervals: a swallowed interval keeps the farthest end (kills m3's plain current.end)", () => {
	assert.deepEqual(mergeIntervals([{ start: 1, end: 10 }, { start: 3, end: 5 }]), [{ start: 1, end: 10 }]);
});

