import test from "node:test";
import assert from "node:assert/strict";
import { mergeIntervals } from "../../src/interval.mjs";

test("mergeIntervals: touching-but-not-overlapping intervals merge (kills m2)", () => {
	assert.deepEqual(mergeIntervals([{ start: 1, end: 3 }, { start: 4, end: 6 }]), [{ start: 1, end: 6 }]);
});

test("mergeIntervals: a swallowed interval must not shrink the merged end (kills m3)", () => {
	assert.deepEqual(mergeIntervals([{ start: 1, end: 10 }, { start: 3, end: 5 }]), [{ start: 1, end: 10 }]);
});

test("mergeIntervals: two ranges that do NOT touch stay separate (baseline)", () => {
	assert.deepEqual(mergeIntervals([{ start: 1, end: 3 }, { start: 5, end: 6 }]), [
		{ start: 1, end: 3 },
		{ start: 5, end: 6 },
	]);
});

